   <a class="skip-link" href="#quiz">Skip to main content</a>

   <main id="quiz">
     <section class="quiz-shell" aria-labelledby="quiz-title">
       <header class="quiz-header">
         <h1 id="quiz-title">Computer Languages Quiz</h1>
         <p class="intro">Select every answer you think fits each question, then submit to see your score.</p>
       </header>

       <form id="quiz-form" novalidate>
         <div class="form-field">
           <fieldset aria-describedby="q1-help">
             <legend>1. Which of these are programming languages?</legend>
             <p class="help-text" id="q1-help">Choose all that apply for this question.</p>
             <div class="choices">
               <label class="choice">
                 <input type="checkbox" name="q1" value="python" data-correct="true">
                 <span><strong>Python</strong><em>General-purpose language used for web, data, and automation.</em></span>
               </label>
               <label class="choice">
                 <input type="checkbox" name="q1" value="html">
                 <span><strong>HTML</strong><em>Markup language for structuring web content.</em></span>
               </label>
               <label class="choice">
                 <input type="checkbox" name="q1" value="javascript" data-correct="true">
                 <span><strong>JavaScript</strong><em>Language that adds interactivity to web pages.</em></span>
               </label>
               <label class="choice">
                 <input type="checkbox" name="q1" value="css">
                 <span><strong>CSS</strong><em>Style sheet language for presentation and layout.</em></span>
               </label>
             </div>
           </fieldset>
         </div>

         <div class="form-field">
           <fieldset>
             <legend>2. Which languages are commonly used for systems programming?</legend>
             <div class="choices">
               <label class="choice">
                 <input type="checkbox" name="q2" value="c" data-correct="true">
                 <span><strong>C</strong><em>Widely used for operating systems and embedded software.</em></span>
               </label>
               <label class="choice">
                 <input type="checkbox" name="q2" value="ruby">
                 <span><strong>Ruby</strong><em>Popular for scripting and web applications.</em></span>
               </label>
               <label class="choice">
                 <input type="checkbox" name="q2" value="rust" data-correct="true">
                 <span><strong>Rust</strong><em>Focuses on performance and memory safety.</em></span>
               </label>
               <label class="choice">
                 <input type="checkbox" name="q2" value="go" data-correct="true">
                 <span><strong>Go</strong><em>Used for cloud services and concurrent systems.</em></span>
               </label>
             </div>
           </fieldset>
         </div>

         <div class="form-field">
           <fieldset>
             <legend>3. Which languages can run in a browser environment?</legend>
             <div class="choices">
               <label class="choice">
                 <input type="checkbox" name="q3" value="javascript" data-correct="true">
                 <span><strong>JavaScript</strong><em>Native browser language for client-side logic.</em></span>
               </label>
               <label class="choice">
                 <input type="checkbox" name="q3" value="swift">
                 <span><strong>Swift</strong><em>Primarily used for Apple platforms and server apps.</em></span>
               </label>
               <label class="choice">
                 <input type="checkbox" name="q3" value="wasm" data-correct="true">
                 <span><strong>WebAssembly</strong><em>Compiled code that can run alongside browser scripts.</em></span>
               </label>
               <label class="choice">
                 <input type="checkbox" name="q3" value="php">
                 <span><strong>PHP</strong><em>Runs on servers before the page reaches the browser.</em></span>
               </label>
             </div>
           </fieldset>
         </div>

         <div class="actions">
           <button type="submit">Submit quiz</button>
           <p class="status" id="quiz-status" aria-live="polite">No answers submitted yet.</p>
         </div>
       </form>
     </section>
   </main>

   <script>
     const form = document.getElementById('quiz-form');
     const status = document.getElementById('quiz-status');
     const questions = [
       { name: 'q1', correct: ['python', 'javascript'] },
       { name: 'q2', correct: ['c', 'rust', 'go'] },
       { name: 'q3', correct: ['javascript', 'wasm'] }
     ];

     form.addEventListener('submit', (event) => {
       event.preventDefault();

       let score = 0;

       questions.forEach((question) => {
         const selections = [...form.querySelectorAll(`input[name="${question.name}"]:checked`)].map((input) => input.value);
         const correctSet = new Set(question.correct);
         const selectedSet = new Set(selections);

         const isCorrect =
           selections.length === question.correct.length &&
           question.correct.every((choice) => selectedSet.has(choice));

         if (isCorrect) {
           score += 1;
         }

         form.querySelectorAll(`input[name="${question.name}"]`).forEach((input) => {
           input.setAttribute('aria-invalid', isCorrect ? 'false' : 'true');
         });
       });

       status.textContent = `You scored ${score} out of ${questions.length}.`;
       status.dataset.state = score === questions.length ? 'success' : 'info';
     });
   </script>
