      padding: 0;
      font-size: 1.1rem;
      font-weight: 700;
      line-height: 1.35;
    }

    .help-text {
      margin: 0.5rem 0 0;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .choices {
      display: grid;
      gap: 0.75rem;
      margin-top: 1rem;
    }

    .choice {
      display: flex;
      gap: 0.75rem;
      align-items: flex-start;
      padding: 0.9rem 1rem;
      border: 1px solid var(--border);
