      background: var(--surface-2);
      cursor: pointer;
      transition: border-color 0.2s ease, background-color 0.2s ease, transform 0.2s ease;
    }

    .choice:hover {
      border-color: #b8c5da;
      background: #e7eef8;
    }

    .choice:has(input:focus-visible) {
      outline: 3px solid var(--accent);
      outline-color: color-mix(in srgb, var(--accent) 38%, white);
      outline-offset: 2px;
    }

    .choice input {
      width: 1.1rem;
      height: 1.1rem;
      margin: 0.15rem 0 0;
      flex: 0 0 auto;
      accent-color: var(--accent);
    }

    .choice span {
      display: block;
      min-width: 0;
    }

    .choice strong {
      display: block;
      font-weight: 650;
    }

    .choice em {
      display: block;
      color: var(--muted);
      font-style: normal;
      font-size: 0.93rem;
    }

    .actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.75rem;
      align-items: center;
      justify-content: space-between;
      padding: 0.5rem 1.25rem 1.5rem;
