    @media (max-width: 40rem) {
      main {
        padding-inline: 0.75rem;
      }

      .quiz-header,
      .form-field,
      .actions {
        padding-left: 1rem;
        padding-right: 1rem;
      }
    }

    @media (forced-colors: active) {
      :root {
        --bg: Canvas;
        --surface: Canvas;
        --surface-2: Canvas;
        --text: CanvasText;
        --muted: CanvasText;
        --border: ButtonBorder;
        --accent: LinkText;
        --accent-2: LinkText;
        --success: ButtonText;
        --shadow: none;
      }

      .quiz-shell,
      .form-field,
      .choice,
      button,
      a.skip-link {
        forced-color-adjust: auto;
      }

      .choice {
        background: Canvas;
      }
